<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {IconBook2,IconPlus,IconRefresh,IconX} from '@tabler/icons-vue'
import {referenceAliases,referenceGroup,searchReferences} from './reference-search'
import {useReferenceWikiLinks} from './reference-wiki'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
type Entry=components['schemas']['ReferenceView']
const props=defineProps<{client:SessionClient;ru:boolean;active:boolean}>()
const {links:wikiLinks,failed:wikiFailed,load:loadWikiLinks,reset:resetWikiLinks}=useReferenceWikiLinks(props.client)
const kinds=['biological-sex','genders','practices','practice-categories','poses','pose-categories','participant-compositions','devices','body-parts','materials','role-scenarios','interaction-formats','venues','health-conditions','allergens','timezones','relationship-types'] as const
const kind=ref<typeof kinds[number]>('biological-sex')
const labels:Record<typeof kinds[number],[string,string]>={'biological-sex':['Biological sex','Биологический пол'],genders:['Gender','Гендер'],practices:['Practices','Практики'],'practice-categories':['Practice categories','Категории практик'],poses:['Poses','Позы'],'pose-categories':['Pose categories','Категории поз'],'participant-compositions':['Participant composition','Состав участников'],devices:['Devices and accessories','Девайсы и аксессуары'],'body-parts':['Body parts','Части тела'],materials:['Materials','Материалы'],'role-scenarios':['Role scenarios','Ролевые сценарии'],'interaction-formats':['Interaction formats','Форматы взаимодействия'],venues:['Venues','Места проведения'],'health-conditions':['Health conditions','Заболевания и состояния'],allergens:['Allergens','Аллергены'],timezones:['Timezones','Часовые пояса'],'relationship-types':['Relationship types','Виды отношений']}
const categorized=computed(()=>kind.value==='practices'||kind.value==='poses')
const title=computed(()=>labels[kind.value][props.ru?1:0])
const categories=ref<Entry[]>([]),categoryUid=ref('')
const compositions=ref<Entry[]>([])
const devices=ref<Entry[]>([]),bodyParts=ref<Entry[]>([]),deviceUids=ref<string[]>([]),bodyPartUids=ref<string[]>([])
const rows=ref<Entry[]>([]),busy=ref(false),saving=ref(false),error=ref(''),saved=ref(false)
const editor=ref<HTMLDialogElement|null>(null),name=ref(''),description=ref(''),icon=ref(''),thumbnail=ref(''),extra=ref('{}')
const query=ref(''),filterCategory=ref(''),filterGroup=ref('')
const groups=computed(()=>[...new Set(rows.value.filter(row=>!categorized.value||!filterCategory.value||row.category_uid===filterCategory.value).map(referenceGroup).filter(Boolean))].sort((a,b)=>a.localeCompare(b)))
watch(filterCategory,()=>{filterGroup.value=''})
const visibleRows=computed(()=>searchReferences(rows.value,query.value,categories.value,categorized.value?filterCategory.value:'',filterGroup.value))
let request=0
const t=(en:string,ru:string)=>props.ru?ru:en
const parsedExtra=computed(()=>{try{const value:unknown=JSON.parse(extra.value);return value!==null&&typeof value==='object'&&!Array.isArray(value)?value as Record<string,components['schemas']['JsonValue']>:null}catch{return null}})
async function load(){const token=++request;const selected=kind.value;busy.value=true;rows.value=[];error.value='';void loadWikiLinks(selected);try{const data=await props.client.get<Entry[]>('/references/'+selected);const [cats,tools,parts,comps]=await Promise.all([selected==='practices'||selected==='poses'?props.client.get<Entry[]>('/references/'+(selected==='poses'?'pose-categories':'practice-categories')):Promise.resolve<Entry[]>([]),selected==='practices'||selected==='poses'?props.client.get<Entry[]>('/references/devices'):Promise.resolve<Entry[]>([]),selected==='practices'?props.client.get<Entry[]>('/references/body-parts'):Promise.resolve<Entry[]>([]),selected==='poses'?props.client.get<Entry[]>('/references/participant-compositions'):Promise.resolve<Entry[]>([])]);if(token===request){rows.value=data;categories.value=cats;devices.value=tools;bodyParts.value=parts;compositions.value=comps}}catch{if(token===request)error.value=t('Could not load catalogue.','Не удалось загрузить справочник.')}finally{if(token===request)busy.value=false}}
watch([()=>props.active,kind],([active])=>{saved.value=false;query.value='';filterCategory.value='';filterGroup.value='';if(active)void load();else resetWikiLinks()},{immediate:true})
function open(){deviceUids.value=[];bodyPartUids.value=[];categoryUid.value='';name.value='';description.value='';icon.value='';thumbnail.value='';extra.value='{}';error.value='';saved.value=false;editor.value?.showModal()}
async function create(){if(saving.value||!parsedExtra.value||!name.value.trim())return;saving.value=true;error.value='';try{await props.client.post('/administration/practices',{device_uids:deviceUids.value,body_part_uids:bodyPartUids.value,category_uid:categoryUid.value||null,name:name.value,description:description.value,icon:icon.value.trim()||null,thumbnail:thumbnail.value.trim()||null,extra:parsedExtra.value});editor.value?.close();await load();saved.value=true}catch(e){error.value=e instanceof Error&&e.message==='REFERENCE_EXISTS'?t('A practice with this name already exists.','Практика с таким названием уже существует.'):t('Could not add practice. Check the fields and your access.','Не удалось добавить практику. Проверьте поля и права доступа.')}finally{saving.value=false}}
</script>
<template>
 <section class="reference-panel" :aria-label="t('Reference catalogues','Справочники')">
  <header class="reference-toolbar"><label>{{t('Catalogue','Справочник')}}<select v-model="kind"><option v-for="id in kinds" :key="id" :value="id">{{labels[id][ru?1:0]}}</option></select></label><div><button v-if="kind==='practices'" :disabled="saving" @click="open"><IconPlus :size="18"/>{{t('Add practice','Добавить практику')}}</button><button class="icon-button" :disabled="busy" :aria-label="t('Reload catalogue','Обновить справочник')" @click="load"><IconRefresh :size="18"/></button></div></header>
  <div class="reference-heading"><h2>{{title}}</h2><span v-if="!busy">{{visibleRows.length}}{{visibleRows.length!==rows.length?` / ${rows.length}`:''}}</span></div>
  <div class="reference-toolbar"><label>{{t('Search','Поиск')}}<input v-model="query" type="search" :placeholder="t('Name or alternative name','Название или альтернативное название')"></label><label v-if="categorized">{{t('Category','Категория')}}<select v-model="filterCategory"><option value="">{{t('All categories','Все категории')}}</option><option v-for="category in categories" :key="category.uid" :value="category.uid">{{category.name}}</option></select></label><label v-if="groups.length">{{t('Group','Группа')}}<select v-model="filterGroup"><option value="">{{t('All groups','Все группы')}}</option><option v-for="group in groups" :key="group" :value="group">{{group}}</option></select></label></div>
  <p v-if="error&&!editor?.open" role="alert">{{error}}</p><p v-if="saved" role="status">{{t('Practice added.','Практика добавлена.')}}</p><p v-if="busy" role="status">{{t('Loading…','Загрузка…')}}</p>
  <p v-if="wikiFailed" role="alert">{{t('Could not load article links. Reload the catalogue.','Не удалось загрузить ссылки на статьи. Обновите справочник.')}}</p>
  <div v-if="!busy" class="reference-table-scroll"><table class="reference-table"><thead><tr><th scope="col">{{t('Name','Название')}}</th><th scope="col">{{t('Description','Описание')}}</th><th scope="col">{{t('Attributes','Атрибуты')}}</th></tr></thead><tbody><tr v-for="entry in visibleRows" :key="entry.uid"><td><img v-if="entry.thumbnail" class="reference-thumbnail" :src="entry.thumbnail" alt="" loading="lazy" width="64" height="64">{{entry.name}}<p v-if="referenceAliases(entry).length" class="muted">{{referenceAliases(entry).join(', ')}}</p><a v-if="wikiLinks[entry.uid]" class="reference-wiki-link" :href="'#wiki?page='+encodeURIComponent(wikiLinks[entry.uid])" :aria-label="t('Read '+entry.name+' in Wiki','Читать '+entry.name+' в Wiki')"><IconBook2 :size="16" aria-hidden="true"/>{{t('Article in Wiki','Статья в Wiki')}}</a></td><td>{{entry.description}}<p v-if="referenceGroup(entry)" class="muted">{{t('Group','Группа')}}: {{referenceGroup(entry)}}</p><p v-if="categorized" class="muted">{{t('Category','Категория')}}: {{categories.find(c=>c.uid===entry.category_uid)?.name??t('None','Не выбрана')}}</p></td><td><details><summary>{{t('Details','Подробнее')}}</summary><dl><dt>uid</dt><dd>{{entry.uid}}</dd><dt>thumbnail</dt><dd>{{entry.thumbnail??t('None','Нет')}}</dd><dt>icon</dt><dd>{{entry.icon??t('None','Нет')}}</dd><dt>url</dt><dd>{{entry.url??t('None','Нет')}}</dd><template v-if="kind==='practices'||kind==='poses'"><dt>{{t('Devices','Девайсы')}}</dt><dd>{{devices.filter(item=>entry.device_uids?.includes(item.uid)).map(item=>item.name).join(', ')||t('None','Не указаны')}}</dd><template v-if="kind==='practices'"><dt>{{t('Body parts','Части тела')}}</dt><dd>{{bodyParts.filter(item=>entry.body_part_uids?.includes(item.uid)).map(item=>item.name).join(', ')||t('None','Не указаны')}}</dd></template><template v-if="kind==='poses'"><dt>{{t('Example compositions','Примеры состава участников')}}</dt><dd>{{compositions.filter(item=>entry.composition_uids?.includes(item.uid)).map(item=>item.name).join(', ')||t('None','Не указаны')}}</dd></template></template><dt>extra</dt><dd><pre>{{JSON.stringify(entry.extra,null,2)}}</pre></dd></dl></details></td></tr></tbody></table><p v-if="!visibleRows.length" class="muted">{{t('No matching entries.','Подходящих записей нет.')}}</p></div>
  <dialog ref="editor" class="practice-editor" aria-labelledby="practice-editor-title" @cancel="saving&&$event.preventDefault()"><header><h2 id="practice-editor-title">{{t('New practice','Новая практика')}}</h2><button class="icon-button" :disabled="saving" :aria-label="t('Close','Закрыть')" @click="editor?.close()"><IconX :size="20"/></button></header><form @submit.prevent="create"><label>{{t('Name','Название')}}<input v-model="name" required maxlength="120" :disabled="saving"></label><label>{{t('Category','Категория')}}<select v-model="categoryUid" :disabled="saving"><option value="">{{t('None','Не выбрана')}}</option><option v-for="category in categories" :key="category.uid" :value="category.uid">{{category.name}}</option></select></label><label>{{t('Description','Описание')}}<textarea v-model="description" rows="3" maxlength="4000" :disabled="saving"/></label><details><summary>{{t('Devices and body parts','Девайсы и части тела')}}</summary><fieldset class="practice-equipment"><legend>{{t('Devices','Девайсы')}}</legend><label v-for="item in devices" :key="item.uid"><input v-model="deviceUids" type="checkbox" :value="item.uid" :disabled="saving">{{item.name}}</label></fieldset><fieldset class="practice-equipment"><legend>{{t('Body parts','Части тела')}}</legend><label v-for="item in bodyParts" :key="item.uid"><input v-model="bodyPartUids" type="checkbox" :value="item.uid" :disabled="saving">{{item.name}}</label></fieldset></details><details><summary>{{t('Additional attributes','Дополнительные атрибуты')}}</summary><label>{{t('Icon path','Путь к иконке')}}<input v-model="icon" maxlength="500" placeholder="/icons/practice.webp" :disabled="saving"></label><label>{{t('Thumbnail path','Путь к миниатюре')}}<input v-model="thumbnail" maxlength="500" placeholder="/references/practice.webp" :disabled="saving"></label><label>extra · JSON<textarea v-model="extra" rows="4" :disabled="saving" spellcheck="false"/></label><p v-if="!parsedExtra" role="alert">{{t('Enter a JSON object.','Укажите JSON-объект.')}}</p></details><p v-if="error" role="alert">{{error}}</p><footer><button :disabled="saving||!parsedExtra||!name.trim()">{{saving?t('Adding…','Добавление…'):t('Add practice','Добавить практику')}}</button><button type="button" :disabled="saving" @click="editor?.close()">{{t('Cancel','Отмена')}}</button></footer></form></dialog>
 </section>
</template>

<style scoped>
.reference-wiki-link{display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:6px 0;color:var(--accent);text-underline-offset:4px;font-size:12px;line-height:1.4}.reference-wiki-link:focus-visible{outline:2px solid currentColor;outline-offset:4px;border-radius:4px}
.reference-thumbnail{display:block;width:64px;height:64px;object-fit:cover;border-radius:10px;margin-bottom:8px}

.practice-equipment label{display:flex;align-items:center;gap:12px;min-height:44px}
.practice-equipment input[type=checkbox]{width:20px;height:20px;min-height:20px;flex:0 0 20px}
</style>
